	'qr_codes.guide_card_2_title' => 'Prilagojeno za tiskanje in uporabo brez povezave',
	'qr_codes.guide_card_2_text' => 'Te kode QR so idealne za letake, vizitke, plakate, brošure, mize na dogodkih, embalažo izdelkov in vse primere, ko ljudje raje skenirajo kot tipkajo.',
	'qr_codes.guide_card_3_title' => 'Pravilno prilagodi in izvozi',
