	'qr_codes.editor.hero_title' => 'Preprosto kodo QR spremenite v ponovno uporabno povezavo med fizičnim in digitalnim svetom',
	'qr_codes.editor.hero_text' => 'Tu koda QR postane praktična, opremljena z blagovno znamko in pripravljena za dejansko uporabo. Vsaka Forever Card Aplikacija ima lahko svojo kodo QR, tukaj pa ločeno ustvarjate in prilagajate kode QR za tisk, kampanje, dogodke, izdelke, deljenje stikov in številne druge načine uporabe s skeniranjem.',
	'qr_codes.editor.hero_card_1_title' => 'Izberite, kaj se zgodi ob skeniranju',
	'qr_codes.editor.hero_card_1_text' => 'Določi, ali naj koda QR odpre URL, stik, plačilo, dostop do omrežja WiFi, sporočilo, dogodek, lokacijo ali katero drugo podprto dejanje.',
	'qr_codes.editor.hero_card_2_title' => 'Oblikujte jo za pravi kontekst',
	'qr_codes.editor.hero_card_2_text' => 'Prilagodite slog, barve, okvir, podobo blagovne znamke in logotip, da se bo koda QR ujemala z letakom, vizitko, listom s podatki o izdelku, predstavitvijo ali gradivom za dogodek.',
	'qr_codes.editor.hero_card_3_title' => 'Preverite pred tiskanjem',
	'qr_codes.editor.hero_card_3_text' => 'Preden kodo QR pošlješ v tisk ali javno distribucijo, uporabi predogled v živo, preverjanje berljivosti in možnosti izvoza.',
	'qr_codes.editor.hero_card_4_title' => 'Ponovno uporabite, namesto da začnete od začetka',
	'qr_codes.editor.hero_card_4_text' => 'Ko koda QR dobro deluje, jo za nove kampanje še naprej urejajte, podvajajte ali izvažajte, namesto da jo vsakič ustvarjate znova.',
	'qr_codes.editor.tour.intro_title' => 'Pregled urejevalnika kod QR',
	'qr_codes.editor.tour.intro_text' => 'Na tej strani lahko ustvariš ali dodelaš samostojno kodo QR, ki jo je mogoče natisniti, deliti, izvoziti in znova uporabiti v različnih okoliščinah.',
	'qr_codes.editor.tour.type_title' => 'Izberite, kaj naj se zgodi ob skeniranju',
	'qr_codes.editor.tour.type_text' => 'Vrsta kode QR določa, kaj se zgodi ob skeniranju: odpiranje povezave, shranjevanje stika, pošiljanje sporočila, povezava z omrežjem WiFi, prikaz podatkov za plačilo in drugo.',
	'qr_codes.editor.tour.basics_title' => 'Začnite z imenom in osnovnimi podatki',
	'qr_codes.editor.tour.basics_text' => 'Kodi QR dodeli jasno interno ime in izpolni osnovna polja z vsebino. To je glavna vsebina, ki bo vgrajena v kodo.',
	'qr_codes.editor.tour.style_title' => 'Oblikujte vzorec kode QR',
	'qr_codes.editor.tour.style_text' => 'Slog določa obliko modulov in očes kode QR. Uporaben je, kadar mora biti koda QR vizualno usklajena z blagovno znamko, kampanjo ali tiskanim gradivom.',
	'qr_codes.editor.tour.colors_title' => 'Nadzirajte kontrast in berljivost',
	'qr_codes.editor.tour.colors_text' => 'Barve niso le stvar videza. Dober kontrast je ključen za zanesljivo skeniranje, zlasti kadar bo koda QR natisnjena ali uporabljena v slabših razmerah.',
	'qr_codes.editor.tour.frame_title' => 'Dodajte kontekst okoli kode QR',
	'qr_codes.editor.tour.frame_text' => 'Okvirji dajo kodi QR jasnejši namen in lahko dodajo poziv k dejanju ali pojasnilo, da uporabnik takoj ve, zakaj naj jo skenira.',
	'qr_codes.editor.tour.branding_title' => 'Previdno dodajte logotip in plasti z elementi blagovne znamke',
	'qr_codes.editor.tour.branding_text' => 'Možnosti oblikovanja blagovne znamke omogočajo dodajanje logotipa in slik v videz kode QR, vendar jih je treba skrbno preizkusiti, da koda ostane dobro berljiva.',
	'qr_codes.editor.tour.options_title' => 'Dokončajte tehnične nastavitve',
	'qr_codes.editor.tour.options_text' => 'Velikost, rob, kodiranje, odpravljanje napak in razvrščanje po projektih pomagajo, da koda QR pravilno deluje po izvozu in pri dejanski uporabi.',
	'qr_codes.editor.tour.preview_title' => 'Spremljajte končno kodo QR v živo',
	'qr_codes.editor.tour.preview_text' => 'V predogledu pred prenosom, tiskanjem ali deljenjem preveriš, ali je koda QR še vedno pregledna in jo je mogoče skenirati.',
