	'qr_codes.editor.tour.download_text' => 'Izvozite datoteko SVG, PNG, JPG ali WEBP, odvisno od tega, ali potrebujete kakovost za tisk, prosojno ozadje, gradivo za predstavitev ali hitro deljenje.',
	'qr_codes.editor.tour.save_title' => 'Shranite, preizkusite in nato uporabite',
